// The icon set: 46 glyphs, authored as SVG paths.
//
// Emoji were doing load-bearing UI work in ~40 places, and they are the wrong
// tool for it: they render differently per OS (Apple and Google art-direct 🔺,
// not us), they cannot be tinted so each arrives with its own baked palette,
// their visual weights are wildly inconsistent, and at the 9–11px chip size
// several were indistinguishable blobs.
//
// These are drawn on the spec's 24×24 grid with a 2px stroke, rounded caps and
// joins, and NO colour of their own — `currentColor` throughout, so the app
// tints every glyph with a token and the colour rule stays enforceable in one
// place. Being vector, they are also crisp at 9px, which is where the emoji
// failed worst.
//
// Deliberately geometric rather than illustrated. Commissioned art can replace
// any of these later without touching a call site: the <Icon name=… /> contract
// is what matters, not who drew the paths.

import React from 'react';
import Svg, { Circle, G, Path, Polygon, Polyline, Rect } from 'react-native-svg';
import { PALETTE } from '../game/constants';

export type IconName =
  // --- Currency & vitals (5) ---
  | 'coin'
  | 'crystal'
  | 'chip'
  | 'alloy'
  | 'hull'
  // --- Boons (14) ---
  | 'shield'
  | 'repair'
  | 'extra-heart'
  | 'damage-up'
  | 'firerate-up'
  | 'nuke'
  | 'bomb'
  | 'freeze'
  | 'slowmo'
  | 'magnet'
  | 'double-coins'
  | 'altitude-surge'
  | 'energy-cell'
  | 'lucky-drop'
  // --- Guns (4) ---
  | 'gun-double'
  | 'gun-bomb'
  | 'gun-laser'
  | 'gun-homing'
  // --- Elite badges (8) ---
  | 'armored'
  | 'rapid'
  | 'regen'
  | 'shielded'
  | 'explosive'
  | 'vampiric'
  | 'swift'
  | 'volatile'
  // --- Navigation & state (12) ---
  | 'play'
  | 'hangar'
  | 'shop'
  | 'objectives'
  | 'stats'
  | 'pause'
  | 'close'
  | 'back'
  | 'lock'
  | 'check'
  | 'chevron'
  | 'info'
  // --- Ribbon marks (3) ---
  | 'flawless'
  | 'speed'
  | 'full-chain'
  // --- Quest & milestone marks (10) ---
  // Beyond the spec's 46: the achievement, milestone and mission catalogs each
  // carry a glyph, and forcing them onto the UI-chrome set produced misleading
  // matches (a boss objective wearing the shield icon, a timer wearing slowmo).
  | 'skull'
  | 'crown'
  | 'medal'
  | 'wave'
  | 'timer'
  | 'gift'
  | 'rocket'
  | 'wrench'
  | 'boss'
  | 'star';

interface Props {
  name: IconName;
  /** Rendered box, px. Every glyph survives 9px. */
  size?: number;
  /** Any token. Defaults to inheriting via currentColor at full white. */
  color?: string;
  /**
   * Filled rather than stroked. The four drawn on falling pickups need to punch
   * through a bright nebula at speed, where a 2px outline disappears.
   */
  filled?: boolean;
  opacity?: number;
}

// Shared stroke geometry, so no glyph can drift off the grid.
const S = 2; // stroke width on the 24-unit grid

/**
 * Imported artwork: one filled silhouette, drawn on its own grid (see VIEWBOX).
 *
 * These come from game-icons.net exports, which ship a coloured backing shape
 * and a baked fill. Both are dropped on the way in — the pickup badge already
 * draws its own disc and family-tinted ring, and a baked colour would break the
 * plasma/amber/violet/gold code that tells the player what a drop does before
 * they've read the glyph.
 *
 * The site also bakes its size slider onto the path as a `transform`; that is
 * dropped too, so the art fills its viewBox instead of sitting at 50% inside a
 * background circle we aren't rendering.
 *
 * `filled` is ignored by design: a silhouette is the readable form at badge
 * size, and the 2px stroke geometry the drawn glyphs share is meaningless at
 * 512 units.
 */
const art = (d: string) => () => <Path fill="currentColor" stroke="none" d={d} />;

/**
 * Glyph bodies. Each returns the SVG children for its viewBox — 24×24 for the
 * drawn glyphs, native scale for imported art; the wrapper supplies colour,
 * stroke width and caps, so a body never repeats them.
 */
