export const ICON_NAMES = Object.keys(GLYPHS) as IconName[];

/**
 * Per-glyph viewBox, for art imported at a grid other than the house 24×24.
 *
 * Re-projecting a thousand-character path onto 24 units by hand is how you get
 * a shield that is subtly off-centre forever, so imported artwork keeps its
 * native coordinates and the wrapper scales it. `size` still means rendered px,
 * which is all any call site cares about.
 *
 * Note these are square even where the art isn't, so a wide glyph renders
 * smaller than its neighbours on a round badge. Cropping the box is the knob to
 * reach for if one reads weak in play.
 */
const IMPORTED = '0 0 512 512';

const VIEWBOX: Partial<Record<IconName, string>> = {
  hull: IMPORTED,
  shield: IMPORTED,
  magnet: IMPORTED,
  repair: IMPORTED,
  'extra-heart': IMPORTED,
  'firerate-up': IMPORTED,
  nuke: IMPORTED,
  bomb: IMPORTED,
  freeze: IMPORTED,
  slowmo: IMPORTED,
  'double-coins': IMPORTED,
  'energy-cell': IMPORTED,
  'lucky-drop': IMPORTED,
  'gun-double': IMPORTED,
};

const HOUSE_VIEWBOX = '0 0 24 24';

/**
 * One component so tinting is never ad-hoc.
 *
 * `currentColor` in the glyph bodies resolves against the `color` prop set on
 * the root <Svg>, which is what lets a single glyph serve as plasma on a shield
 * bubble and threat on an elite badge without a second asset.
 */
function IconBase({ name, size = 16, color = PALETTE.ink, filled = false, opacity = 1 }: Props) {
  const body = GLYPHS[name];
  if (!body) return null;
  return (
    <Svg width={size} height={size} viewBox={VIEWBOX[name] ?? HOUSE_VIEWBOX} opacity={opacity}>
      <G
        color={color}
        fill="none"
        stroke="currentColor"
        strokeWidth={S}
        strokeLinecap="round"
        strokeLinejoin="round"
      >
        {body(filled)}
      </G>
    </Svg>
  );
}

// Memoized: several of these sit in the HUD, whose parent re-renders every frame.
// The props are primitives, so this reconciles only when the glyph or its tint
// actually changes.
export const Icon = React.memo(IconBase);
export default Icon;
